class RightMenu{static activeInstance=null;constructor(options={}){this.options=Object.assign({selector:null,theme:'light',items:[],minWidth:200,className:'',onShow:null,onHide:null,onSelect:null},options);this.rootMenu=null;this.activeStack=[];this.activeTarget=null;this.init()}
init(){if(!this.options.selector&&!this.options.triggers){console.error('RightMenu: No selector provided.');return}
$(document).on('contextmenu',this.options.selector,(e)=>this.handleRightMenu(e));$(document).on('click',(e)=>this.handleClickOutside(e));$(document).on('keydown',(e)=>this.handleKeyDown(e))}
handleRightMenu(e){e.preventDefault();e.stopPropagation();if(RightMenu.activeInstance&&RightMenu.activeInstance!==this){RightMenu.activeInstance.hideAll()}
this.hideAll();this.activeTarget=e.currentTarget;if(typeof this.options.onShow==='function'){const shouldShow=this.options.onShow(this.activeTarget);if(shouldShow===!1)return}
RightMenu.activeInstance=this;this.rootMenu=this.createMenu(this.options.items,!0);this.activeStack=[this.rootMenu];this.showMenu(this.rootMenu,e.pageX,e.pageY)}
createMenu(items,isRoot=!1){const menuEl=$('<ul>').addClass('right-menu-plugin').addClass(this.options.theme==='dark'?'cm-theme-dark':'cm-theme-light').addClass(this.options.className).css('min-width',this.options.minWidth+'px');if(!isRoot){menuEl.addClass('rightmenu-submenu')}
items.forEach(item=>{if(item.separator){menuEl.append($('<li>').addClass('right-menu-separator'));return}
if(item.header){menuEl.append($('<li>').addClass('right-menu-header').text(item.header));return}
let isVisible=!0;if(typeof item.visible==='function')isVisible=item.visible(this.activeTarget);else if(item.visible===!1)isVisible=!1;if(!isVisible)return;let isDisabled=!1;if(typeof item.disabled==='function')isDisabled=item.disabled(this.activeTarget);else if(item.disabled===!0)isDisabled=!0;const li=$('<li>').addClass('right-menu-item');if(isDisabled)li.addClass('disabled');const iconSpan=$('<span>').addClass('right-menu-icon');if(item.icon)iconSpan.append($('<i>').addClass(item.icon));li.append(iconSpan);const labelSpan=$('<span>').addClass('right-menu-label').text(item.label);li.append(labelSpan);if(item.shortcut){li.append($('<span>').addClass('right-menu-shortcut').text(item.shortcut))}
if(item.items&&item.items.length>0){li.addClass('has-submenu');li.append($('<span>').addClass('right-menu-submenu-arrow'));const submenu=this.createMenu(item.items,!1);li.append(submenu)}else{li.on('click',(e)=>{if(isDisabled)return;e.stopPropagation();const data=this.activeTarget?$(this.activeTarget).data():{};if(item.action){item.action(data,this.activeTarget)}
if(this.options.onSelect){this.options.onSelect(item,this.activeTarget)}
this.hideAll()})}
menuEl.append(li)});if(isRoot){$('body').append(menuEl)}
return menuEl}
showMenu(menuEl,x,y){menuEl.addClass('visible');const winW=$(window).width();const winH=$(window).height();const menuW=menuEl.outerWidth();const menuH=menuEl.outerHeight();let finalX=x;if(x+menuW>winW){finalX=winW-menuW-10}
let finalY=y;if(y+menuH>winH){finalY=winH-menuH-10}
menuEl.css({top:finalY,left:finalX})}
hideAll(){if(this.rootMenu){this.rootMenu.removeClass('visible');const menuToRemove=this.rootMenu;setTimeout(()=>menuToRemove.remove(),200);this.rootMenu=null}
this.activeStack=[];if(typeof this.options.onHide==='function'&&RightMenu.activeInstance===this){this.options.onHide(this.activeTarget)}
if(RightMenu.activeInstance===this){RightMenu.activeInstance=null}}
handleClickOutside(e){if(RightMenu.activeInstance!==this)return;if(this.rootMenu&&!$(e.target).closest('.right-menu-plugin').length){this.hideAll()}}
handleKeyDown(e){if(RightMenu.activeInstance!==this)return;if(this.activeStack.length===0)return;const currentMenu=this.activeStack[this.activeStack.length-1];const items=currentMenu.children('li.right-menu-item:not(.disabled)');let activeItem=currentMenu.children('li.right-menu-item.active');let index=items.index(activeItem);switch(e.key){case 'ArrowDown':e.preventDefault();index++;if(index>=items.length)index=0;this.focusItem(currentMenu,items.eq(index));break;case 'ArrowUp':e.preventDefault();index--;if(index<0)index=items.length-1;this.focusItem(currentMenu,items.eq(index));break;case 'ArrowRight':e.preventDefault();if(activeItem.length&&activeItem.hasClass('has-submenu')){const submenu=activeItem.children('.rightmenu-submenu');if(submenu.length){this.activeStack.push(submenu);const firstSubItem=submenu.children('li.right-menu-item:not(.disabled)').first();this.focusItem(submenu,firstSubItem)}}
break;case 'ArrowLeft':e.preventDefault();if(this.activeStack.length>1){this.activeStack.pop();const parentMenu=this.activeStack[this.activeStack.length-1]}
break;case 'Enter':e.preventDefault();if(activeItem.length){if(activeItem.hasClass('has-submenu')){const submenu=activeItem.children('.rightmenu-submenu');if(submenu.length){this.activeStack.push(submenu);const firstSubItem=submenu.children('li.right-menu-item:not(.disabled)').first();this.focusItem(submenu,firstSubItem)}}else{activeItem.trigger('click')}}
break;case 'Escape':e.preventDefault();this.hideAll();break}}
focusItem(menu,item){menu.children('.right-menu-item').removeClass('active');item.addClass('active')}}